function resolveIconKey(name: string): string | null {
  const clean = name.toLowerCase().trim();
  if (svgIconMap[clean]) return clean;

  if (clean.includes("react")) return "react";
  if (clean.includes("vue")) return "vue";
  if (clean.includes("typescript") || clean === "ts") return "typescript";
  if (clean.includes("javascript") || clean === "js") return "javascript";
  if (clean.includes("tailwind")) return "tailwindcss";
  if (clean.includes("bootstrap")) return "bootstrap";
  if (clean.includes("html")) return "html";
  if (clean.includes("css")) return "css";
  if (clean.includes("node")) return "nodejs";
  if (clean.includes("express")) return "express";
  if (clean.includes("laravel")) return "laravel";
  if (clean.includes("golang") || clean === "go") return "golang";
  if (clean.includes("android")) return "android";
  if (clean.includes("flutter")) return "flutter";
  if (clean.includes("kotlin")) return "kotlin";
  if (clean.includes("python")) return "python";
  if (clean.includes("github")) return "github";
  if (clean.includes("gitlab")) return "gitlab";
  if (clean.includes("git")) return "git";
  if (clean.includes("linkedin")) return "linkedin";
  if (clean.includes("mysql")) return "mysql";
  if (clean.includes("postgres")) return "postgresql";
  if (clean.includes("google cloud") || clean.includes("compute engine") || clean === "gcp") return "gcp";
  if (clean.includes("docker")) return "docker";
  if (clean.includes("linux")) return "linux";
  if (clean.includes("figma")) return "figma";
  if (clean.includes("excel")) return "excel";
  if (clean.includes("word")) return "word";
  if (clean.includes("powerpoint")) return "powerpoint";
  if (clean.includes("office")) return "office";

  return null;
}

export function FallbackLibraryIcon({ name, className, size = 16 }: { name: string; className?: string; size?: number }) {
  const clean = name.toLowerCase();

  if (clean.includes("api") || clean.includes("rest")) {
    return <Network size={size} className={className} />;
  }
  if (clean.includes("jwt") || clean.includes("auth") || clean.includes("security")) {
    return <KeyRound size={size} className={className} />;
  }
  if (clean.includes("storage") || clean.includes("cloud")) {
    return <HardDrive size={size} className={className} />;
  }
  if (clean.includes("hardware") || clean.includes("troubleshoot")) {
    return <Wrench size={size} className={className} />;
  }
  if (clean.includes("network") || clean.includes("wifi")) {
    return <Wifi size={size} className={className} />;
  }
  if (clean.includes("installation") || clean.includes("software")) {
    return <Package size={size} className={className} />;
  }
  if (clean.includes("doc") || clean.includes("technical")) {
    return <FileCode2 size={size} className={className} />;
  }
  if (clean.includes("responsive") || clean.includes("mobile")) {
    return <Smartphone size={size} className={className} />;
  }
  if (clean.includes("inertia") || clean.includes("ui")) {
    return <Layers size={size} className={className} />;
  }
  if (clean.includes("server")) {
    return <Server size={size} className={className} />;
  }

  return <Code2 size={size} className={className} />;
}

export function TechIcon({
  name,
  className = "w-4 h-4 shrink-0",
  size = 16,
  ...props
}: {
  name: string;
  className?: string;
  size?: number | string;
} & SVGProps<SVGSVGElement>) {
  const iconKey = resolveIconKey(name);

  if (iconKey && svgIconMap[iconKey]) {
    return (
      <span className="inline-flex items-center justify-center shrink-0">
        {svgIconMap[iconKey]({ className, size, ...props })}
      </span>
    );
  }

  return (
    <span className="inline-flex items-center justify-center shrink-0 text-(--color-muted)">
      <FallbackLibraryIcon name={name} className={className} size={typeof size === "number" ? size : 16} />
    </span>
  );
}